	(197, 4, 'TIMBER', 'Timber', 'SLAB_001', 'Timber Frame SJ90 I-Joist (39 x 90) 300\nBoQ', 'Slab', 'A1-A3 Slabs', 2, 'Cavity insulation (thermal/acoustic)', 'Mineral wool', 2.4000, NULL, 0.222000, NULL, 14, 0.305827, 80.00, NULL, 1.250000, 30.5827, 5.309500, '2025-09-22 12:34:48', '2025-09-22 12:34:48'),
	(198, 4, 'TIMBER', 'Timber', 'SLAB_001', 'Timber Frame SJ90 I-Joist (39 x 90) 300\nBoQ', 'Slab', 'A1-A3 Slabs', 3, 'Joist stiffener (LVL)', 'Laminated Veneer Lumber (400 spacing)', 2.4000, NULL, 0.090000, NULL, 14, 0.117936, 595.92, NULL, 0.390000, 27.4094, 4.758570, '2025-09-22 12:34:48', '2025-09-22 12:34:48'),
