	(201, 4, 'TIMBER', 'Timber', 'SLAB_002', 'Timber Frame WebJoist SJ12 304\nBoQ', 'Slab', 'A1-A3 Slabs', 2, 'Joist chord (TR26 timber; top & bottom chords @ 400 c/c)', 'TR 26 Timber (47 x 97 - 400 spacing)', 2.4000, NULL, 0.047000, NULL, 14, 0.153182, 544.00, NULL, 0.330000, 27.4993, 4.774185, '2025-09-22 12:34:48', '2025-09-22 12:34:48'),
	(202, 4, 'TIMBER', 'Timber', 'SLAB_002', 'Timber Frame WebJoist SJ12 304\nBoQ', 'Slab', 'A1-A3 Slabs', 3, 'Rim board / Edge joist (perimeter member)', 'End timber element (47 x 97)', 2.3000, NULL, 0.047000, NULL, 2, 0.020971, 544.00, NULL, 0.330000, 3.7648, 0.653609, '2025-09-22 12:34:48', '2025-09-22 12:34:48'),
